/**
 * GET /agents/query?q=<terms>&limit=N — deterministic passage retrieval over
 * Mike Jones' public knowledge-base export (T-2026-10-09-871).
 *
 * Read-only, keyless, no LLM in the path. Serves /agents/kb/search-index.json
 * from this deploy's own static assets (generated by scripts/kb-to-agents.mjs
 * through the same default-deny/redaction pipeline as the markdown fact
 * sheets), scores passages locally, and returns citable results with their
 * source path under /agents/kb/*.md.
 *
 * Security: exposes ONLY content already public in /agents/kb/. No write
 * surface, no auth wall, no external calls. CORS open on GET (data is public).
 */
import { scoreEntries, tokenize } from './scorer.mjs';

const INDEX_PATH = '/agents/kb/search-index.json';
const DEFAULT_LIMIT = 5;
const MAX_LIMIT = 20;

const JSON_HEADERS = {
  'content-type': 'application/json; charset=utf-8',
  'access-control-allow-origin': '*',
  'cache-control': 'public, max-age=300',
};

const json = (data, status = 200) => new Response(JSON.stringify(data), { status, headers: JSON_HEADERS });

export async function onRequestGet({ request, env }) {
  const url = new URL(request.url);
  const q = (url.searchParams.get('q') || '').trim();
  if (!q) {
    return json(
      {
        error: 'missing q',
        usage: '/agents/query?q=<terms>&limit=5',
        example: url.origin + '/agents/query?q=Xbox%20patent&limit=3',
      },
      400
    );
  }

  const limit = Math.min(Math.max(parseInt(url.searchParams.get('limit') || String(DEFAULT_LIMIT), 10) || DEFAULT_LIMIT, 1), MAX_LIMIT);

  let entries;
  try {
    const res = await loadAsset(env, url, INDEX_PATH);
    if (!res.ok) return json({ error: 'search index unavailable', upstreamStatus: res.status }, 503);
    const index = await res.json();
    entries = index.entries || [];
  } catch (err) {
    return json({ error: 'search index unavailable', detail: String(err) }, 503);
  }

  const { words, results } = scoreEntries(entries, q, limit);

  const body = {
    query: q,
    terms: words,
    count: results.length,
    results,
    cite: 'Passages come from the public fact sheets; cite by the returned path under https://mikejones.online.',
  };
  if (!results.length) {
    body.hint = 'No scored passage for those terms. Try fewer or broader terms, or browse /llms.txt and /agents/kb/index.json directly.';
  }
  return json(body);
}

export async function onRequestOptions() {
  return new Response(null, {
    status: 204,
    headers: {
      ...JSON_HEADERS,
      'access-control-allow-methods': 'GET, OPTIONS',
      'access-control-allow-headers': 'content-type',
    },
  });
}

/** Prefer the deploy's own ASSETS binding; fall back to a same-origin fetch. */
async function loadAsset(env, url, path) {
  if (env && env.ASSETS && typeof env.ASSETS.fetch === 'function') {
    return env.ASSETS.fetch(new Request(new URL(path, url)));
  }
  return fetch(new URL(path, url));
}